public class StringBuilderDemo {
    public static void main(String[] args) {
        // 1. Initializing with capacity
        StringBuilder sb = new StringBuilder(64);

        // 2. Chained appends of multiple data types
        sb.append("Order #")
          .append(1024)
          .append(" [")
          .append("CONFIRMED")
          .append("]");

        System.out.println("Constructed: " + sb.toString());

        // 3. Inserting text at an index
        sb.insert(0, "URGENT: ");
        System.out.println("After Insert: " + sb.toString());

        // 4. Deleting a slice [start, end)
        sb.delete(0, 8); // Removes "URGENT: "
        System.out.println("After Delete: " + sb.toString());

        // 5. In-place reversal
        StringBuilder word = new StringBuilder("LearnBySelf");
        word.reverse();
        System.out.println("Reversed: " + word.toString());

        // 6. Capacity vs Length
        StringBuilder demo = new StringBuilder("Java");
        System.out.println("Length: " + demo.length());     // 4 (characters stored)
        System.out.println("Capacity: " + demo.capacity()); // 20 (16 default + 4)
    }
}

