public class NumberListBuilder {
    public static void main(String[] args) {
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= 5; i++) {
            if (i > 1) {
                sb.append(", ");
            }
            sb.append(i);
        }
        System.out.println("Numbers: " + sb.toString());
    }
}

